var getTechnicianProDB = async (query) => {
  const {
    searchTerm,
    location,
    minRating,
    minExperience,
    maxHourlyRate,
    sortBy = "createdAt",
    sortOrder = "desc",
    page = 1,
    limit = 10
  } = query;
  const pageNum = Number(page) > 0 ? Number(page) : 1;
  const limitNum = Number(limit) > 0 ? Number(limit) : 10;
  const skip = (pageNum - 1) * limitNum;
  const andConditions = [
    { role: Role.TECHNICIAN },
    { status: UserStatus.ACTIVE },
    { isDeleted: false }
  ];
  if (searchTerm) {
    andConditions.push({
      technicianProfile: {
        OR: [
          { bio: { contains: String(searchTerm), mode: "insensitive" } },
          { skills: { hasSome: [String(searchTerm)] } }
        ]
      }
    });
  }
  if (location) {
    andConditions.push({
      technicianProfile: {
        location: { contains: String(location), mode: "insensitive" }
      }
    });
  }
  if (minRating) {
    andConditions.push({
      technicianProfile: {
        averageRating: { gte: Number(minRating) }
      }
    });
  }
  if (minExperience) {
    andConditions.push({
      technicianProfile: {
        experience: { gte: Number(minExperience) }
      }
    });
  }
  if (maxHourlyRate) {
    andConditions.push({
      technicianProfile: {
        hourlyRate: { lte: Number(maxHourlyRate) }
      }
    });
  }
  const whereConditions = { AND: andConditions };
  let orderByCondition = {};
  const profileFields = ["averageRating", "hourlyRate", "experience"];
  const direction = String(sortOrder).toLowerCase() === "asc" ? "asc" : "desc";
  if (profileFields.includes(String(sortBy))) {
    orderByCondition = {
      technicianProfile: {
        [String(sortBy)]: direction
      }
    };
  } else {
    orderByCondition = {
      [String(sortBy)]: direction
    };
  }
  const [total, data] = await Promise.all([
    prisma.user.count({ where: whereConditions }),
    prisma.user.findMany({
      where: whereConditions,
      select: {
        id: true,
        name: true,
        email: true,
        phone: true,
        avatar: true,
        address: true,
        role: true,
        status: true,
        createdAt: true,
        technicianProfile: true
      },
      orderBy: orderByCondition,
      skip,
      take: limitNum
    })
  ]);
  const totalPage = Math.ceil(total / limitNum);
  return {
    meta: {
      page: pageNum,
      limit: limitNum,
      total,
      totalPage
    },
    data
  };
};
