var userBasicSelect2 = {
  id: true,
  name: true,
  email: true
};
var createReviewInDB = async (payload, customerId) => {
  const { bookingId, rating, comment } = payload;
  if (!bookingId || rating === void 0 || rating === null) {
    throw new Error("bookingId and rating are required");
  }
  if (typeof rating !== "number" || rating < 1 || rating > 5) {
    throw new Error("Rating must be a number between 1 and 5");
  }
  const booking = await prisma.booking.findUnique({
    where: { id: bookingId }
  });
  if (!booking) {
    const error = new Error("Booking not found");
    error.statusCode = 404;
    throw error;
  }
  if (booking.customerId !== customerId) {
    const error = new Error(
      "Forbidden: You can only review your own bookings"
    );
    error.statusCode = 403;
    throw error;
  }
  if (booking.paymentStatus !== PaymentStatus.COMPLETED) {
    throw new Error("You can only leave a review for completed bookings");
  }
  const existingReview = await prisma.review.findUnique({
    where: { bookingId }
  });
  if (existingReview) {
    throw new Error("A review has already been submitted for this booking");
  }
  const technicianId = booking.technicianId;
  const createdReview = await prisma.$transaction(async (tx) => {
    const newReview = await tx.review.create({
      data: {
        bookingId,
        customerId,
        technicianId,
        rating,
        comment: comment || null
      }
    });
    const reviewStats = await tx.review.aggregate({
      where: { technicianId },
      _avg: {
        rating: true
      },
      _count: {
        id: true
      }
    });
    const averageRating = reviewStats._avg.rating || 0;
    const completedJobs = reviewStats._count.id;
    await tx.technicianProfile.updateMany({
      where: { userId: technicianId },
      data: {
        averageRating: parseFloat(averageRating.toFixed(2)),
        completedJobs
      }
    });
    return newReview;
  });
  const result = await prisma.review.findUnique({
    where: { id: createdReview.id },
    include: {
      booking: true,
      customer: {
        select: userBasicSelect2
      },
      technician: {
        select: userBasicSelect2
      }
    }
  });
  return result;
};
var getAllReviewsFromDB = async () => {
  const reviews = await prisma.review.findMany({
    include: {
      booking: true,
      customer: {
        select: userBasicSelect2
      },
      technician: {
        select: userBasicSelect2
      }
    },
    orderBy: {
      createdAt: "desc"
    }
  });
  return reviews;
};
var getSingleReviewFromDB = async (reviewId) => {
  const review = await prisma.review.findUnique({
    where: { id: reviewId },
    include: {
      booking: true,
      customer: {
        select: userBasicSelect2
      },
      technician: {
        select: userBasicSelect2
      }
    }
  });
  if (!review) {
    const error = new Error("Review not found");
    error.statusCode = 404;
    throw error;
  }
  return review;
};
